import hashlib
msgs=[b"Message 1: Give me the flag", b"Message 2: Give me the flag", b"Message 3: Give me the flag"]
rs=[r1,r2,r3]
ss=[s1,s2,s3]
hs=[int.from_bytes(hashlib.sha256(m).digest(),'big')%q for m in msgs]

# Derive polynomial from recurrence:
# k3 = a + k1^2 - b*k2
# substitute k_i=(h_i+x r_i)/s_i
# clear denominators and solve quadratic in x
from math import prod
inv1,inv2,inv3 = inverse(s1,q), inverse(s2,q), inverse(s3,q)
# w_i + x v_i forms
w=[(hs[i]*inverse(ss[i],q))%q for i in range(3)]
v=[(rs[i]*inverse(ss[i],q))%q for i in range(3)]
# Equation: w3 + xv3 = a + (w1+xv1)^2 - b*(w2+xv2)
# expand: (v1^2) x^2 + (2w1v1 - b v2 - v3)x + (w1^2 - b w2 + a - w3)=0
A = (a*v[0]*v[0])%q
B = (a*2*w[0]*v[0] - b*v[1] - v[2])%q
C = (a*w[0]*w[0] - b*w[1] - w[2])%q
# Solve quadratic mod q
# brute force via Tonelli-like all roots using exponent since q prime and small chance two roots
D = (B*B - 4*A*C) % q
# sqrt mod q
root = pow(D, (q+1)//4, q) if q%4==3 else None
print('q mod 4', q%4)
# use brute force with pow(D,(q+1)//2) check not enough
# We'll use sympy if available? implement Tonelli

def tonelli(n,p):
    assert pow(n,(p-1)//2,p)==1
    if p%4==3:
        return pow(n,(p+1)//4,p)
    q1=p-1; s=0
    while q1%2==0:
        s+=1; q1//=2
    z=2
    while pow(z,(p-1)//2,p)!=p-1:
        z+=1
    m=s; c=pow(z,q1,p); t=pow(n,q1,p); r=pow(n,(q1+1)//2,p)
    while t!=1:
        i=1; tt=pow(t,2,p)
        while tt!=1:
            tt=pow(tt,2,p); i+=1
        b=pow(c,1<<(m-i-1),p)
        m=i; c=(b*b)%p; t=(t*c)%p; r=(r*b)%p
    return r

if pow(D,(q-1)//2,q)==1:
    sqrtD=tonelli(D,q)
    roots=[((-B+sqrtD)*inverse((2*A)%q,q))%q, ((-B-sqrtD)*inverse((2*A)%q,q))%q]
    print('roots', roots)
    for x in roots:
        print(long_to_bytes(x))
else:
    print('no square')